return ['domain'=>'page-builder-sandwich','plural-forms'=>'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<10 || n%100>=20) ? 1 : 2);','language'=>'sr_RS','project-id-version'=>'page-builder-sandwich','pot-creation-date'=>'2026-09-26T16:59:17+00:00','po-revision-date'=>'2026-09-26T16:59:17+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Page Builder Sandwich'=>'Page Builder Sandwich','https://zinndigital.com/wordpress-plugins/page-builder-sandwich'=>'https://zinndigital.com/wordpress-plugins/page-builder-sandwich','The foundation release of the rebuilt Page Builder Sandwich: a settings and About screen, a footprint-free front-end output layer, and one sample content block.'=>'Inicijalno izdanje redizajniranog Page Builder Sandwich-a: ekran sa podešavanjima i O programu, izlazni sloj na korisničkoj strani bez SEO otiska i jedan uzorak sadržajnog bloka.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','AI providers'=>'AI provajderi','The makers of ChatGPT. A good all-rounder.'=>'Tvorci modela ChatGPT. Dobar svestrani izbor.','The makers of Claude. Strong at writing and careful reasoning.'=>'Tvorci Claude modela. Snažan u pisanju i pažljivom zaključivanju.','Google\'s Gemini models. Fast and inexpensive.'=>'Google-ovi Gemini modeli. Brzi i povoljni.','A European AI company with fast, inexpensive models.'=>'Evropska kompanija za veštačku inteligenciju sa brzim i povoljnim modelima.','Low-cost models that are good at writing and code.'=>'Jeftini modeli koji su dobri u pisanju i pisanju koda.','One key for models from many different providers.'=>'Jedan ključ za modele od mnogo različitih provajdera.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Bilo koja usluga koja radi kao OpenAI-jev API, uključujući model koji se pokreće na vašem sopstvenom računaru ili serveru.','General (used when nothing more specific is set)'=>'Opšte (koristi se kada nije podešeno ništa specifičnije)','Writing and rewriting'=>'Pisanje i prepisivanje','Translation'=>'Prevod','Code and CSS'=>'Код и CSS','Sorry, you are not allowed to access this page.'=>'Žao nam je, nemate pristup ovoj stranici.','These settings are shared by every plugin that uses them: %s.'=>'Ova podešavanja deli svaki dodatak koji ih koristi: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Vaši ključevi su šifrovani u bazi podataka ovog sajta i šalju se samo i isključivo provajderu kojeg ste izabrali — nikada nama.','Step 1 of 2: choose an AI provider'=>'Korak 1 od 2: izaberite AI provajdera','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Donosite sopstveni ključ, tako da provajderu plaćate direktno ono što potrošite. Niste sigurni? Bilo koja od ovih opcija dobro funkcionisane; kasnije možete dodati još.','Next'=>'Sledeće','Step 2 of 2: connect %s'=>'Korak 2 od 2: povežite %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Unesite adresu svoje OpenAI-kompatibilne usluge koja se završava sa /v1. Ključ je potreban samo ako ga usluga zatraži.','Open %s and sign in (or create a free account).'=>'Otvorite %s i prijavite se (ili kreirajte besplatan nalog).','the %s API keys page'=>'stranica za %s API ključeve','Create a new key and copy it.'=>'Kreirajte novi ključ i kopirajte ga.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Nalepite ga ispod i pritisnite „Sačuvaj i testiraj“. Šaljemo jedan mali zahtev da proverimo da li radi.','Most providers need a little credit on the account before a key works: %s.'=>'Većini provajdera je potrebno malo kredita na nalogu pre nego što ključ počne da radi: %s.','add credit'=>'dodaj kredit','← Choose a different provider'=>'← Izaberite drugog provajdera','Address'=>'Adresa','Saved key ends in …%s — paste a new one to replace it'=>'Sačuvani ključ se završava sa …%s — nalepite novi da biste ga zamenili','Key (optional)'=>'Ključ (opciono)','API key'=>'API ključ','Save and test'=>'Sačuvaj i testiraj','Providers'=>'Ponuđači','Provider'=>'Dobavljač','Status'=>'Status','Key'=>'Кључ','Get a key'=>'Preuzmite ključ','Test'=>'Тест','Remove'=>'Ukloni','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Sačuvano novijom verzijom dodatka: ažurirajte ovaj dodatak ili ponovo unesite ključ.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'Sačuvani ključ se više ne može otvoriti (bezbednosni ključevi sajta su promenjeni). Unesite ga ponovo.','Not connected'=>'Nije povezano','Connected — last test passed %s'=>'Povezano — poslednji test je uspeo %s','Last test failed: %s'=>'Poslednji test nije uspeo: %s','Connected — not tested yet'=>'Povezano — još uvek nije testirano','Which model to use'=>'Koji model koristiti','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ označava našu preporuku za taj zadatak. Lista uključuje svaki model koji vaš ključ može da koristi, učitan uživo od provajdera.','— Recommended for the provider —'=>'— Preporučeno za provajdera —','Save models'=>'Sačuvaj modele','Refresh the model lists from the providers'=>'Osvežite liste modela od dobavljača','best quality'=>'najbolji kvalitet','lowest cost'=>'najniža cena','fastest'=>'najbrže','Add a model yourself'=>'Dodajte model sami','A model came out today? Paste its exact name to use it straight away.'=>'Novi model se pojavio danas? Nalepite njegov tačan naziv da biste ga odmah koristili.','Model name'=>'Naziv modela','Add model'=>'Dodaj model','Recommended models list'=>'Lista preporučenih modela','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Lista preporučenih modela nije mogla biti verifikovana, tako da se preporuke ne prikazuju. Ponovo instalirajte dodatak ili uključite dnevna ažuriranja u nastavku.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'Lista koja se koristi objavljena je %s. Svako ažuriranje dodatka donosi novu.','Also check Zinn Digital® once a day for an updated list.'=>'Takođe proveravajte Zinn Digital® jednom dnevno radi ažurirane liste.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Šalje se samo običan zahtev za preuzimanje: bez ključa, bez adrese sajta, ništa o vašem sadržaju. Lista je potpisana, a lista koja ne prođe provere potpisa se ignoriše.','Last checked %1$s: %2$s.'=>'Poslednji put provereno %1$s: %2$s.','Save, and check now if turned on'=>'Sačuvajte i proveri odmah ako je uključeno','a newer list was installed'=>'instalirana je novija lista','already up to date'=>'već ažurirano','the download failed the signature check and was ignored'=>'preuzimanje nije uspelo proveru potpisa i zanemareno je','Zinn Digital® could not be reached; the current list stays in use'=>'Zinn Digital® nije dostupan; trenutna lista ostaje u upotrebi','turned off'=>'isključen','Open'=>'Отвори','Check their status page'=>'Proverite njihovu stranicu sa statusom','Open your billing page'=>'Otvorite svoju stranicu za naplatu','Open your API keys page'=>'Otvorite stranicu sa API ključevima','Open the AI settings'=>'Otvorite AI podešavanja','Sorry, you are not allowed to do that.'=>'Žao nam je, nemate dozvolu za to.','Unknown provider.'=>'Nepoznati provajder.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Unesite adresu svoje usluge, na primer http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'To ne liči na API ključ. Kopirajte ga ponovo, bez razmaka.','Paste your API key first.'=>'Prvo nalepite svoj API ključ.','Key removed.'=>'Ključ je uklonjen.','Models saved.'=>'Modeli su sačuvani.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Unesite tačan naziv modela, na primer onako kako je navedeno u dokumentaciji provajdera.','Added %s. Choose it under "Which model to use".'=>'Dodato je %s. Izaberite ga pod opcijom „Koji model da koristite“.','Model removed.'=>'Model je uklonjen.','Daily updates are off. The list that came with the plugin is used.'=>'Dnevna ažuriranja su isključena. Koristi se lista koja je stigla uz dodatak.','Checked: %s.'=>'Označeno: %s.','Model lists refreshed.'=>'Liste modela su osvežene.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Vaš AI ključ je sačuvala novija verzija jednog od vaših dodataka. Ažurirajte ovaj dodatak ili ponovo unesite ključ u AI podešavanjima.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Vaš sačuvani AI ključ se više ne može otvoriti (bezbednosni ključevi sajta su promenjeni). Unesite ga ponovo u AI podešavanjima.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'Veštačka inteligencija još nije podešena. Dodajte ključ za AI provajdera u AI podešavanjima.','No model is chosen for this task. Pick one in the AI settings.'=>'Nijedan model nije izabran za ovaj zadatak. Izaberite jedan u AI podešavanjima.','That AI provider is not supported by this version of the plugin.'=>'Taj AI provádzač nije podržan od strane ove verzije dodatka.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Ovaj sajt nije mogao da uspostavi vezu sa vašim AI servisom. Proverite da li je pokrenut i da li je njegova adresa dostupna sa vašeg veb-servera (servis na vašem sopstvenom računaru nije dostupan sa hostovanog sajta).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Ovaj sajt nije mogao da uspostavi vezu sa %s. Proverite njihovu stranicu sa statusom; ako rade, vaš host možda blokira odlazne veze ili je adresa pogrešna.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s navodi da vaš nalog nema više kredita ili kvote. Dodajte kredit ili povećajte limit na svom nalogu kod njih, pa pokušajte ponovo.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s nije prihvatio vaš ključ. Možda je pogrešno unet, opozvan ili je istekao. Kreirajte novi ključ i nalepite ga ovde.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s je odbio ovaj zahtev za vaš ključ. Ključ možda nema pristup ovom modelu ili funkciji, ili je potrebno da verifikujete svoj nalog.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Model "%1$s" nije dostupan od %2$s za vaš ključ. Izaberite drugi model u AI podešavanjima.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'Vaš %2$s paket ne uključuje model „%1$s“. Izaberite drugi model u podešavanjima za veštačku inteligenciju ili nadogradite svoj paket kod njih.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s ograničava brzinu kojom vaš ključ može da šalje zahteve. Sačekajte minut i pokušajte ponovo, ili povećajte ograničenje broja zahteva kod njih.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s trenutno ima probleme (prekid rada ili preopterećenje sa njihove strane). Sa vašim podešavanjima je sve u redu. Pokušajte ponovo uskoro.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'AI zahtev nije uspeo iz razloga koji nismo mogli da identifikujemo. Pokušajte ponovo; ako se to ponovi, obratite se podršci sa detaljima u nastavku.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'AI provajder je odgovorio u formatu koji ovaj dodatak nije mogao da pročita. Pokušajte ponovo; ako se to ponovi, izaberite drugi model ili se obratite podršci.','Custom (OpenAI-compatible)'=>'Prilagođeno (kompatibilno sa OpenAI)','Save a key for this provider first.'=>'Prvo sačuvajte ključ za ovog provajdera.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Vaš ključ radi, ali provajder ne navodi nijedan model teksta za njega. Dodajte model sami ispod.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Povezano. %1$s je odgovorio/la koristeći %2$s. Vaše AI funkcije su spremne za upotrebu.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Vaša korisniska uloga nema dozvolu za korišćenje veštačke inteligencije na ovom sajtu. Obratite se administratoru.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Ovaj sajt je dostigao mesečni limit potrošnje za veštačku inteligenciju. Administrator može da ga poveća u podešavanjima za veštačku inteligenciju.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Ovaj sajt je dostigao mesečni limit AI zahteva. Administrator ga može povećati u AI podešavanjima.','Usage and cost'=>'Potrošnja i troškovi','The log, limits and role permissions apply to AI used through: %s.'=>'Dnevnik, ograničenja i dozvole uloga primenjuju se na veštačku inteligenciju koja se koristi preko: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Troškovi su približni, izračunati na osnovu objavljenih cena; model sa nepoznatom cenom računa se kao nula.','This month: %1$s requests, about %2$s.'=>'Ovaj mesec: %1$s zahteva, oko %2$s.','When'=>'Kada','Who'=>'Ко','Used for'=>'Користи се за','Model'=>'Model','Tokens in / out'=>'Tokeni u / izlaz','About'=>'О нама','Result'=>'Rezultat','No AI requests have been made yet.'=>'Još uvek nisu upućeni nikakvi zahtevi ka veštačkoj inteligenciji.','Done'=>'Završeno','Limits and permissions'=>'Ограничења и дозволе','Monthly spending limit (US dollars)'=>'Mesečni limit potrošnje (US dolari)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Ostavite prazno za bez ograničenja. Veštačka inteligencija se zaustavlja do kraja meseca kada približni trošak dostigne tu vrednost.','Monthly request limit'=>'Ограничење месечних захтева','Leave empty for no limit.'=>'Ostavite prazno za bez ograničenja.','Who may use AI'=>'Ko može da koristi veštačku inteligenciju','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Označite ništa da biste omogućili svima koji mogu da koriste funkcije dodatka da koriste veštačku inteligenciju. Administratori uvek mogu da je koriste.','Save limits and permissions'=>'Sačuvaj ograničenja i dozvole','Limits and permissions saved.'=>'Ograničenja i dozvole su sačuvani.','Security error, please refresh the page and try again.'=>'Bezbednosna greška, osvežite stranicu i pokušajte ponovo.','Missing newsletter settings. Please contact the admin.'=>'Nedostaju podešavanja biltena. Molimo kontaktirajte administratora.','Invalid newsletter settings. Please contact the admin.'=>'Nevažeća podešavanja biltena. Molimo kontaktirajte administratora.','Invalid email address.'=>'Nevažeća adresa e-pošte.','Too many attempts. Please try again in a few minutes.'=>'Previše pokušaja. Molimo pokušajte ponovo za nekoliko minuta.','Something went wrong. Please contact the admin.'=>'Došlo je do greške. Molimo vas da kontaktirate administratora.','Map'=>'Мапирај','Background video'=>'Pozadinski video','%1$s: %2$d font files stored, stylesheet %3$s'=>'%1$s: sačuvano %2$d fajlova fontova, stilski list %3$s','That family is not stored.'=>'Ta porodica nije sačuvana.','Removed.'=>'Uklonjeno.','That is not a valid font family name.'=>'To nije važeće ime porodice fontova.','Google Fonts did not return that family. Check the name and try again.'=>'Google Fonts nije vratio tu familiju. Proverite naziv i pokušajte ponovo.','The font files could not be downloaded or saved. Check that the uploads folder is writable.'=>'Datoteke fontova nije bilo moguće preuzeti ili sačuvati. Proverite da li je fascikla za otpremanje (uploads) upisiva.','The font stylesheet could not be saved. Check that the uploads folder is writable.'=>'Stylesheet font-a nije mogao biti sačuvan. Proverite da li je folder za otpremanje (uploads) upisiv.','The admin screen\'s scripts are missing from this copy of the plugin. Reinstall it from a released package.'=>'Skripte administratorskog ekrana nedostaju u ovoj kopiji dodatka. Ponovo je instalirajte iz objavljenog paketa.','This screen needs JavaScript.'=>'Ovaj ekran zahteva JavaScript.','Languages'=>'Jezici','Upgrade'=>'Nadogradite','Pricing'=>'Cene','Start Trial'=>'Započni probni period','Account'=>'Nalog','Contact Us'=>'Kontaktirajte nas','Affiliation'=>'Pripadnost','the kind of softwarePlugin'=>'Dodatak','greetingHey %s,'=>'Zdravo %s,','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info. This will help us make the %s more compatible with your site and better at doing what you need it to.'=>'Prijavite se da primate imejl obaveštenja za bezbednosna i ažuriranja funkcija, edukativni sadržaj i povremene ponude, kao i da delite neke osnovne informacije o WordPress okruženju. Ovo će nam pomoći da %s učinimo kompatibilnijim sa vašim sajtom i boljim u obavljanju onoga za šta vam je potreban.','Opt in to get email notifications for security & feature updates, educational content, and occasional offers, and to share some basic WordPress environment info.'=>'Prijavite se da primate obaveštenja putem e-pošte za bezbednosna i ažuriranja funkcija, edukativni sadržaj i povremene ponude, kao i da delite osnovne informacije o WordPress okruženju.','If you skip this, that\'s okay! %1$s will still work just fine.'=>'Ako ovo preskočite, u redu je! %1$s će i dalje raditi sasvim normalno.','Allow & Continue'=>'Dozvoli i nastavi','verbSkip'=>'Preskoči','Skipping, please wait'=>'Preskakanje, sačekajte','Continue'=>'Nastavi','Please wait'=>'Molimo sačekajte','as activating pluginActivating'=>'Aktiviranje','This will allow %s to'=>'Ovo će omogućiti da %s','Privacy Policy'=>'Politika privatnosti','Terms of Service'=>'Uslovi korišćenja','License Agreement'=>'Licencni ugovor','Have a license key?'=>'Imate ključ licence?','Activate License'=>'Aktiviraj licencu','View Basic Profile Info'=>'Pregledajte osnovne informacije profila','Your WordPress user\'s: first & last name, and email address'=>'Ime, prezime i adresa e-pošte vašeg WordPress korisnika','View Basic Website Info'=>'Pogledajte osnovne informacije o veb-sajtu','Homepage URL & title, WP & PHP versions, and site language'=>'URL i naslov početne strane, verzije WP-a i PHP-a, i jezik sajta','View Basic %s Info'=>'Pregledajte osnovne %s informacije','Current %s & SDK versions, and if active or uninstalled'=>'Trenutne %s i SDK verzije, i da li su aktivne ili deinstalirane','Newsletter'=>'Bilten','Updates, announcements, marketing, no spam'=>'Ažuriranja, obaveštenja, marketing, bez neželjene pošte','View Diagnostic Info'=>'Prikaži dijagnostičke informacije','WordPress & PHP versions, site language & title'=>'WordPress & PHP verzije, jezik i naziv sajta','View Plugins & Themes List'=>'Прикажи листу додатака и тема','Names, slugs, versions, and if active or not'=>'Nazivi, skraćeni nazivi (slugs), verzije i podatak da li su aktivni ili ne','optional'=>'opciono','Never miss an important update'=>'Nikada ne propustite važnu ispravku','We have introduced this opt-in so you never miss an important update and help us make the %s more compatible with your site and better at doing what you need it to.'=>'Uveli smo ovu opciju prijave kako nikada ne biste propustili važno ažuriranje i kako biste nam pomogli da učinimo %s kompatibilnijim sa vašim sajtom i efikasnijim u obavljanju onoga što vam je potrebno.','Thank you for updating to %1$s v%2$s!'=>'Hvala vam što ste ažurirali na %1$s v%2$s!','The prefix must be 1 to 8 lowercase letters or digits, start with a letter, and must not name the plugin.'=>'Prefiks mora imati od 1 do 8 malih slova ili cifara, počinjati slovom i ne sme predstavljati naziv dodatka.','You are not allowed to edit this item.'=>'Nije vam dozvoljeno da izmenite ovu stavku.','You are not allowed to do this.'=>'Nemate dozvolu za ovo.','Safe mode was turned off because it no longer matches your login. Reload the page.'=>'Bezbedni režim je isključen zato što se više ne poklapa sa vašom prijavom. Ponovo učitajte stranicu.','Only an administrator can use safe mode.'=>'Samo administrator može da koristi bezbedni režim.','Safe mode needs a normal browser login.'=>'Bezbedan režim zahteva prijavljivanje preko standardnog pregledača.','Safe mode could not be set up.'=>'Bezbedni režim nije mogao da se podesi.','Safe mode needs write access to the wp-content/mu-plugins folder.'=>'Bezbednom režimu je potreban pristup za pisanje u fasciklu wp-content/mu-plugins.','Safe mode could not write to the wp-content/mu-plugins folder.'=>'Bezbedni režim nije mogao da upiše u folder wp-content/mu-plugins.','Sandwich Studio'=>'Sandwich Studio','That page does not exist, or it has been deleted.'=>'Ta stranica ne postoji ili je obrisana.','Sorry, you are not allowed to edit this item in Sandwich Studio.'=>'Žao nam je, nemate dozvolu da uređujete ovu stavku u aplikaciji Sandwich Studio.','Sandwich Studio is not built. Reinstall the plugin.'=>'Sandwich Studio nije izgrađen. Ponovo instalirajte dodatak.','Add title'=>'Dodaj naslov','Type / to choose a block'=>'Unesite / da izaberete blok','Loading Sandwich Studio…'=>'Učitavanje aplikacije Sandwich Studio…','Sandwich Studio needs JavaScript. Use the normal editor instead.'=>'Sandwich Studio zahteva JavaScript. Umesto toga koristite običan uređivač.','Edit “%s” with Sandwich Studio'=>'Uredi „%s“ pomoću Sandwich Studio','Edit with Sandwich Studio'=>'Izmeni u Sandwich Studio','Blank canvas'=>'Prazno platno','A migration step is running right now. Try again in a minute.'=>'Korak migracije je trenutno u toku. Pokušajte ponovo za minut.','Thank you for subscribing!'=>'Hvala vam na pretplati!','Something went wrong. Please contact the administrator.'=>'Došlo je do greške. Molimo kontaktirajte administratora.','Years'=>'Godine','Months'=>'Meseći','Weeks'=>'Nedelje','Days'=>'Dani','Hours'=>'Sati','Minutes'=>'Minuti','Seconds'=>'Sekunde','Go to slide %d'=>'Idi na slajd %d','You\'re already subscribed to our newsletter'=>'Već ste pretplaćeni na naš bilten','Email address is already subscribed.'=>'Email adresa je već prijavljena.','MailPoet plugin not found. Please contact the admin.'=>'MailPoet dodatak nije pronađen. Molimo kontaktirajte administratora.','Built by Neil Lock, CEO of Zinn Digital® Ltd'=>'Izradio Neil Lock, izvršni direktor kompanije Zinn Digital® Ltd','Version %s'=>'Verzija %s','Page Builder Sandwich website'=>'Page Builder Sandwich veb-sajt','Zinn Digital® website'=>'Zinn Digital® veb-sajt','Settings saved.'=>'Podešavanja su sačuvana.','See the Pro plans and pricing'=>'Pogledajte Pro planove i cene','Front-end output'=>'Izlaz na front-endu','Class name prefix'=>'Prefiks imena klase','Every class name the plugin prints on your pages starts with this prefix, so the pages do not reveal which plugin built them. 1 to 8 lowercase letters or digits, starting with a letter.'=>'Svako ime klase koje dodatak ispisuje na vašim stranicama počinje ovim prefiksom, tako da se na stranicama ne vidi koji je dodatak napravio. 1 do 8 malih slova ili cifara, počevši od slova.','Save'=>'Sačuvaj','Beta updates'=>'Бета ажурирања','This site receives beta versions as updates.'=>'Ovaj sajt prima beta verzije kao ažuriranja.','This site receives stable versions only.'=>'Ovaj sajt prima samo stabilne verzije.','Change this on the Account page'=>'Promenite ovo na stranici Nalog','Beta versions are offered to licensed Pro installations that are connected to their account. Once connected, you can join from the Account page.'=>'Beta verzije su dostupne licenciranim Pro instalacijama koje su povezane sa njihovim nalogom. Kada se povežete, možete se pridružiti sa stranice Nalog.','The request converting this post stopped before it finished, so the post was skipped. Open it to convert it, or convert it again from here.'=>'Zahtev za konverziju ove objave je zaustavljen pre nego što je završen, tako da je objava preskočena. Otvorite je da biste je konvertovali ili je ponovo konvertujte odavde.','There is no backup of this post to restore.'=>'Nema rezervne kopije ove objave za vraćanje.','The converted content could not be saved.'=>'Konvertovani sadržaj nije mogao biti sačuvan.','Unknown error.'=>'Nepoznata greška.','No legacy content has been checked yet.'=>'Još uvek nije proveren nijedan stari sadržaj.','Restoring legacy content: %1$d of %2$d posts.'=>'Vraćanje starog sadržaja: %1$d od %2$d objavljenih članaka.','Converting legacy content: %1$d of %2$d posts.'=>'Konvertovanje nasleđenog sadržaja: %1$d od %2$d objavljenih članaka.','Undo finished: %1$d restored, %2$d failed.'=>'Poništavanje je završeno: %1$d je vraćeno, %2$d nije uspelo.','Conversion finished: %1$d converted, %2$d unchanged, %3$d failed.'=>'Konverzija završena: %1$d konvertovano, %2$d nepromenjeno, %3$d nije uspelo.','Legacy content'=>'Zastareli sadržaj','Pages made with earlier versions of Page Builder Sandwich are converted to blocks in the background. Every post is backed up first, so each conversion can be undone.'=>'Stranice napravljene pomoću ranijih verzija dodatka Page Builder Sandwich automatski se konvertuju u blokove u pozadini. Svaka objava se najpre rezervno kopira, tako da se svaka konverzija može opozvati.','%d post still holds legacy content.'=>'%d post i dalje sadrži stari sadržaj.' . "\0" . '%d objava i dalje sadrži stari sadržaj.' . "\0" . '%d objava i dalje sadrži stari sadržaj.','%d post has a backup.'=>'%d објава има резервну копију.' . "\0" . '%d objava ima rezervnu kopiju.' . "\0" . '%d objava ima rezervnu kopiju.','%d post could not be handled'=>'%d objavu nije bilo moguće obraditi' . "\0" . '%d objjava nije moglo biti obrađeno' . "\0" . '%d objjava nije moglo biti obrađeno','Post %d'=>'Objava %d','Conversion started. It continues in the background; you can leave this page.'=>'Konverzija je započeta. Ona se nastavlja u pozadini; možete napustiti ovu stranicu.','Convert legacy content'=>'Konvertuj stari sadržaj','Restore every converted post to its legacy content? Changes made to those posts since they were converted will be lost.'=>'Da li želite da vratite svaku konvertovanu objavu na njen stari sadržaj? Promene koje su napravljene na tim objavama od njihove konverzije biće izgubljene.','Undo started. It continues in the background; you can leave this page.'=>'Poništavanje je počelo. Nastavlja se u pozadini; možete napustiti ovu stranicu.','Undo all conversions'=>'Poništi sva pretvaranja','Shortcode tag'=>'Kod kratkog koda','Use letters, numbers, dashes and underscores only.'=>'Koristite samo slova, brojeve, crtice i donje crte.','Attribute name'=>'Naziv atributa','Add attribute'=>'Dodaj atribut','Content'=>'Садржај','Shortcode'=>'Kratki kod','Choose a shortcode tag in the block settings.'=>'Izaberite oznaku kratkog koda u podešavanjima bloka.','The "%s" control from the old editor is not available in the block editor. Enter the value as text.'=>'Kontrola „%s“ iz starog uređivača nije dostupna u uređivaču blokova. Unesite vrednost kao tekst.','Choose image'=>'Izaberi sliku','Choose file'=>'Izaberi datoteku','— Default —'=>'— Podrazumevano —','Advanced styling'=>'Napredno stilizovanje','Inline CSS'=>'Inline CSS','CSS declarations, for example: min-height: 380px; background-color: #333'=>'CSS deklaracije, na primer: min-height: 380px; background-color: #333','Effects (legacy classes)'=>'Efekti (zastarele klase)','Space-separated effect names carried over from older versions, for example: hover-shadow'=>'Imena efekata razdvojena razmakom preneta iz starijih verzija, na primer: hover-shadow','Row'=>'Red','Width'=>'Širina','Content width'=>'Širina sadržaja','Full width'=>'Puna širina','Full width, content kept in the middle'=>'Puna širina, sadržaj centriran','Link'=>'Веза','Link address'=>'Адреса везе','Open in a new tab'=>'Otvorite u novoj kartici','Link relationship'=>'Odnos veze','Alignment'=>'Poravnanje','None'=>'Nijedan','Left'=>'Levo','Centre'=>'Centriraj','Right'=>'Десно','Button text'=>'Tekst dugmeta','Add text…'=>'Dodajte tekst…','Icon'=>'Ikona','SVG markup'=>'SVG oznaka','Scripts, links and external references are removed before the icon is shown.'=>'Skripte, linkovi i spoljne reference se uklanjaju pre nego što se ikona prikaže.','Accessible label'=>'Pristupačna oznaka','Leave empty for a decorative icon.'=>'Оставите празно за декоративну икону.','Paste SVG markup in the block settings.'=>'Nalepite SVG oznake u podešavanja bloka.','New setting name'=>'Naziv nove postavke','For example: title or text'=>'Na primer: naslov ili tekst','Add setting'=>'Dodaj podešavanje','Widget'=>'Виџет','Choose a widget'=>'Izaberite vidžet','Widget area'=>'Oblast vidžeta','Choose a widget area'=>'Izaberite oblast vidzeta','This image has no width and height, so the page will jump when it loads. Choose it from the Media Library, or set its width and height.'=>'Ova slika nema širinu ni visinu, pa će se stranica pomeriti prilikom učitavanja. Izaberite je iz biblioteke medija ili podesite njenu širinu i visinu.','This video is not from the Media Library, so its size is unknown and the page will jump when it loads. Upload it to the Media Library instead.'=>'Ovaj video-zapis nije iz Mediateke, tako da mu je veličina nepoznata i stranica će poskočiti kada se učita. Umesto toga, otpremite ga u Mediateku.','An image, video or frame in this HTML has no width and height, so the page will jump when it loads. Add width and height attributes to it.'=>'Jedna slika, video ili frejm u ovom HTML-u nema širinu i visinu, tako da će se stranica pomerati kada se učita. Dodajte im atribute za širinu i visinu.','This embed resizes itself after it loads, which moves the content below it. Give it room or place it lower on the page.'=>'Ovaj ugrađeni sadržaj se automatski prilagođava po učitavanju, što pomera sadržaj ispod njega. Obezbedite mu dovoljno prostora ili ga postavite niže na stranici.','Layout shift'=>'Pomeranje rasporeda','Heading'=>'Naslov','Text'=>'Tekst','Style'=>'Stil','Plain'=>'Obično','Accent'=>'Акцент','No languages to switch between. The switcher appears when a translation plugin lists two or more languages.'=>'Nema jezika za prebacivanje. Prekidač se pojavljuje kada dodatak za prevod navede dva ili više jezika.','Switcher'=>'Prebacivač','Show the current language'=>'Prikaži trenutni jezik','%s is also editing this page. Saving may overwrite their changes.'=>'%s takođe uređuje ovu stranicu. Čuvanje može prepisati njihove izmene.','Block library'=>'Biblioteka blokova','Layers'=>'Slojevi','Close panel'=>'Zatvori panel','Page canvas'=>'Platno stranice','Revisions'=>'Reverzije','Block 